export default function ContactoPage() { const whatsappHref = getStudioWhatsAppHref("Hola, quisiera consultar con 13 Studio Tattoo."); return <section className="min-h-screen bg-[#050505] px-5 py-20 text-[#dedee3]"><div className="mx-auto max-w-3xl border border-[#2b2b31] bg-[var(--studio-carbon)] p-8"><p className="text-xs font-bold uppercase tracking-[.3em] text-[#FF00A8]">Contacto</p><h1 className="mt-4 text-5xl font-black">HABLEMOS DE TU IDEA.</h1><p className="mt-6 max-w-xl leading-7 text-[#a3a3ad]">Contanos qué tenés en mente desde el formulario. Revisaremos tu solicitud y te contactaremos; enviarla no confirma un turno.</p><Link href="/turnos" className="studio-primary mt-8 inline-flex bg-[#B7FF00] px-6 py-3 font-bold text-[#050505]">SOLICITAR TURNO</Link>{whatsappHref ? <a href={whatsappHref} target="_blank" rel="noopener noreferrer" className="studio-book mt-4 inline-flex">Escribinos por WhatsApp <i>↗</i></a> : null}</div></section>; }
